// PyBind wrapper for sketch2model function
// This module exposes the full MonsterMash/Teddy sketch2model implementation

// CRITICAL: Include pre-include header FIRST, before ANY other includes
// This ensures Eigen macros are defined before any Eigen headers are included
// (including indirect includes through pybind11 or other headers)
#include "preinclude.h"

#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>
#include <pybind11/stl.h>
// Note: We don't include pybind11/eigen.h to avoid Eigen IterativeLinearSolvers issues
// Instead, we'll manually convert Eigen matrices to numpy arrays
#include <vector>
#include <string>
#include <iostream>
#include <fstream>
#include <stdexcept>

// Include MonsterMash headers using our wrapper to ensure Eigen macros are defined first
#include "wrapper.h"
#include "image/image.h"

namespace py = pybind11;

// Helper function to convert numpy array to Imguc
Imguc numpy_to_imguc(py::array_t<uint8_t> arr) {
    py::buffer_info buf_info = arr.request();
    
    if (buf_info.ndim != 2 && buf_info.ndim != 3) {
        throw std::runtime_error("Input array must be 2D (grayscale) or 3D (RGB)");
    }
    
    int width, height, channels;
    if (buf_info.ndim == 2) {
        height = buf_info.shape[0];
        width = buf_info.shape[1];
        channels = 1;
    } else {
        height = buf_info.shape[0];
        width = buf_info.shape[1];
        channels = buf_info.shape[2];
    }
    
    // Create Imguc using constructor
    Imguc img(width, height, channels, -1);
    
    // Copy data
    // Imguc data layout: data[ch*(y*w+x)+channel]
    // numpy layout: row-major, for (H,W) or (H,W,C)
    uint8_t* data_ptr = static_cast<uint8_t*>(buf_info.ptr);
    
    if (buf_info.ndim == 2) {
        // Grayscale: numpy (H, W) -> Imguc (w, h, 1)
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                // numpy: [y, x], Imguc: (x, y, channel)
                img(x, y, 0) = data_ptr[y * width + x];
            }
        }
    } else {
        // Multi-channel: numpy (H, W, C) -> Imguc (w, h, ch)
        // numpy stores as [y][x][c], Imguc expects channel-interleaved
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                for (int c = 0; c < channels; c++) {
                    // numpy: [y, x, c], Imguc: (x, y, c)
                    img(x, y, c) = data_ptr[(y * width + x) * channels + c];
                }
            }
        }
    }
    
    return img;
}

// Helper function to save mesh to OBJ file
void save_mesh_to_obj(const Eigen::MatrixXd& vertices, 
                      const Eigen::MatrixXi& faces,
                      const std::string& filename) {
    std::ofstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Cannot open file for writing: " + filename);
    }
    
    file << "# Generated by Teddy/MonsterMash sketch2model\n";
    file << "# Vertices: " << vertices.rows() << ", Faces: " << faces.rows() << "\n\n";
    
    // Write vertices
    for (int i = 0; i < vertices.rows(); i++) {
        file << "v " << vertices(i, 0) << " " 
             << vertices(i, 1) << " " 
             << vertices(i, 2) << "\n";
    }
    
    file << "\n";
    
    // Write faces (OBJ uses 1-based indexing)
    for (int i = 0; i < faces.rows(); i++) {
        file << "f " << (faces(i, 0) + 1) << " " 
             << (faces(i, 1) + 1) << " " 
             << (faces(i, 2) + 1) << "\n";
    }
    
    file.close();
}

// Main wrapper function
std::string teddy_sketch2model(
    py::array_t<uint8_t> outline_img,
    py::array_t<uint8_t> region_img,
    const std::string& output_path,
    const std::string& triangle_opts = "pqa25QYY",
    int subs_factor = 2,
    int smooth_factor = 10,
    double default_inflation = 2.0,
    const std::vector<double>& region_inflations = std::vector<double>()
) {
    try {
        // Convert numpy arrays to Imguc
        Imguc outline = numpy_to_imguc(outline_img);
        Imguc region = numpy_to_imguc(region_img);
        
        // Create vectors
        std::vector<Imguc> outline_imgs = {outline};
        std::vector<Imguc> region_imgs = {region};
        
        // Output matrices
        Eigen::MatrixXd vertices;
        Eigen::MatrixXi faces;
        
        // Call sketch2model
        bool success = sketch2model(
            outline_imgs,
            region_imgs,
            vertices,
            faces,
            triangle_opts,
            subs_factor,
            smooth_factor,
            default_inflation,
            region_inflations
        );
        
        if (!success) {
            throw std::runtime_error("sketch2model failed");
        }
        
        // Save to OBJ file
        save_mesh_to_obj(vertices, faces, output_path);
        
        return output_path;
        
    } catch (const std::exception& e) {
        throw std::runtime_error(std::string("teddy_sketch2model error: ") + e.what());
    }
}

// Alternative function that returns vertices and faces as numpy arrays
py::tuple teddy_sketch2model_arrays(
    py::array_t<uint8_t> outline_img,
    py::array_t<uint8_t> region_img,
    const std::string& triangle_opts = "pqa25QYY",
    int subs_factor = 2,
    int smooth_factor = 10,
    double default_inflation = 2.0,
    const std::vector<double>& region_inflations = std::vector<double>()
) {
    try {
        // Convert numpy arrays to Imguc
        Imguc outline = numpy_to_imguc(outline_img);
        Imguc region = numpy_to_imguc(region_img);
        
        // Create vectors
        std::vector<Imguc> outline_imgs = {outline};
        std::vector<Imguc> region_imgs = {region};
        
        // Output matrices
        Eigen::MatrixXd vertices;
        Eigen::MatrixXi faces;
        
        // Call sketch2model
        bool success = sketch2model(
            outline_imgs,
            region_imgs,
            vertices,
            faces,
            triangle_opts,
            subs_factor,
            smooth_factor,
            default_inflation,
            region_inflations
        );
        
        if (!success) {
            throw std::runtime_error("sketch2model failed");
        }
        
        // Manually convert Eigen matrices to numpy arrays
        // vertices: MatrixXd (N x 3) -> numpy array
        py::array_t<double> vertices_array({vertices.rows(), vertices.cols()});
        auto vertices_buf = vertices_array.mutable_unchecked<2>();
        for (int i = 0; i < vertices.rows(); i++) {
            for (int j = 0; j < vertices.cols(); j++) {
                vertices_buf(i, j) = vertices(i, j);
            }
        }
        
        // faces: MatrixXi (M x 3) -> numpy array
        py::array_t<int> faces_array({faces.rows(), faces.cols()});
        auto faces_buf = faces_array.mutable_unchecked<2>();
        for (int i = 0; i < faces.rows(); i++) {
            for (int j = 0; j < faces.cols(); j++) {
                faces_buf(i, j) = faces(i, j);
            }
        }
        
        return py::make_tuple(vertices_array, faces_array);
        
    } catch (const std::exception& e) {
        throw std::runtime_error(std::string("teddy_sketch2model_arrays error: ") + e.what());
    }
}

PYBIND11_MODULE(teddy_sketch2model, m) {
    m.doc() = "PyBind wrapper for MonsterMash/Teddy sketch2model function";
    
    m.def("sketch2model", &teddy_sketch2model,
          "Convert sketch outline and region images to 3D mesh (saves to OBJ file)",
          py::arg("outline_img"),
          py::arg("region_img"),
          py::arg("output_path"),
          py::arg("triangle_opts") = "pqa25QYY",
          py::arg("subs_factor") = 2,
          py::arg("smooth_factor") = 10,
          py::arg("default_inflation") = 2.0,
          py::arg("region_inflations") = std::vector<double>());
    
    m.def("sketch2model_arrays", &teddy_sketch2model_arrays,
          "Convert sketch outline and region images to 3D mesh (returns numpy arrays)",
          py::arg("outline_img"),
          py::arg("region_img"),
          py::arg("triangle_opts") = "pqa25QYY",
          py::arg("subs_factor") = 2,
          py::arg("smooth_factor") = 10,
          py::arg("default_inflation") = 2.0,
          py::arg("region_inflations") = std::vector<double>());
}

